<?php
require dirname(__DIR__).'/app/bootstrap.php';
if(admin_logged_in())redirect('webyonet/');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$u=trim($_POST['username']??'');$p=$_POST['password']??'';$ip=$_SERVER['REMOTE_ADDR']??'';$s=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE username=? AND ip_address=? AND created_at>=DATE_SUB(NOW(),INTERVAL 15 MINUTE)');$s->execute([$u,$ip]);if((int)$s->fetchColumn()>=5)$error='Çok fazla hatalı giriş. 15 dakika sonra tekrar deneyin.';else{$s=db()->prepare('SELECT * FROM admins WHERE username=? AND is_active=1 LIMIT 1');$s->execute([$u]);$a=$s->fetch();if($a&&password_verify($p,$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$a['id'];$_SESSION['admin_username']=$a['username'];db()->prepare('DELETE FROM login_attempts WHERE username=? AND ip_address=?')->execute([$u,$ip]);redirect('webyonet/');}else{db()->prepare('INSERT INTO login_attempts(username,ip_address,created_at) VALUES(?,?,NOW())')->execute([$u,$ip]);$error='Kullanıcı adı veya şifre hatalı.';}}}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TOPLUCA WebYönet</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f5f7;font-family:Arial;color:#171717}.wrap{min-height:100vh;display:grid;place-items:center;padding:20px}.box{width:min(420px,100%);background:#fff;padding:34px;border-radius:18px;box-shadow:0 20px 60px #0001}.logo{font-size:30px;font-weight:900}.logo span{color:#ff5a00}.sub{color:#777;font-size:13px;margin-bottom:25px}label{display:block;font-size:12px;font-weight:800;margin:14px 0}input{width:100%;padding:12px;margin-top:6px;border:1px solid #ddd;border-radius:8px}button{width:100%;padding:13px;border:0;border-radius:8px;background:#ff5a00;color:#fff;font-weight:900}.err{background:#fff0f0;color:#a22;padding:10px;border-radius:8px}</style></head><body><div class="wrap"><form class="box" method="post"><?=csrf_field()?><div class="logo">TOPLU<span>CA</span></div><div class="sub">WebYönet • Yönetim Merkezi</div><?php if($error):?><div class="err"><?=h($error)?></div><?php endif;?><label>Kullanıcı Adı<input name="username" autocomplete="username" required></label><label>Şifre<input type="password" name="password" autocomplete="current-password" required></label><button>Giriş Yap</button></form></div></body></html>
